import re
import sys

values = {}
order = ["a", "b", "c", "d", "e", "f", "g", "h", "i", "j",
         "k", "l", "m", "n", "o", "p", "TMP"]

assignment = re.compile(
    r"([A-Za-z]+)\s*<-\s*(?:(\d+)|\(([A-Za-z]+)\s*\+\s*(\d+)\)\s*mod\s*100)\s*;"
)

for line in sys.stdin:
    line = line.strip()
    if not line or line.startswith("//"):
        continue

    match = assignment.fullmatch(line)
    if not match:
        continue

    variable, literal, source, increment = match.groups()
    if literal is not None:
        values[variable] = int(literal)
    else:
        values[variable] = (values[source] + int(increment)) % 100

print("; ".join(f"{name} ?= {values[name]}" for name in order) + ";")
